mapper.select:
SELECT COUNTRY_ID AS countryId, COUNTRY_NAME AS countryName, REGION_ID AS regionId FROM COUNTRIES
AND REGION_ID = #{regionId}
ORDER BY COUNTRY_ID

SELECT L.LOCATION_ID AS locationId, L.ADDRESS AS address, L.POSTAL_CODE AS postalCode, L.CITY AS city, L.STATE AS state, L.COUNTRY_ID AS countryId, L.ADDRESS AS locationName FROM LOCATIONS L, COUNTRIES C
AND L.COUNTRY_ID = C.COUNTRY_ID
AND C.REGION_ID = #{regionId}
AND L.COUNTRY_ID = #{countryId}
ORDER BY L.LOCATION_ID

SELECT W.WAREHOUSE_ID AS warehouseId, W.WAREHOUSE_NAME AS warehouseName, R.REGION_ID AS regionId, R.REGION_NAME AS regionName, C.COUNTRY_ID AS countryId, C.COUNTRY_NAME AS countryName, L.LOCATION_ID AS locationId, L.ADDRESS AS locationName FROM WAREHOUSES W, LOCATIONS L, COUNTRIES C, REGIONS R
AND W.LOCATION_ID = L.LOCATION_ID AND L.COUNTRY_ID = C.COUNTRY_ID AND C.REGION_ID = R.REGION_ID
AND R.REGION_ID = #{regionId}
AND C.COUNTRY_ID = #{countryId}
AND L.LOCATION_ID = #{locationId}
ORDER BY W.WAREHOUSE_ID

mapper.insert:

    SELECT
        #{regionId}|| '_' || #{countryId}|| '_' || #{locationId}
        || '_' || TO_CHAR(
            NVL(
                MAX(
                    TO_NUMBER(
                        SUBSTR(W.WAREHOUSE_ID, INSTR(W.WAREHOUSE_ID, '_', -1) + 1)
                    )
                ),
                0
            ) + 1 
        ) AS warehouseId
       FROM WAREHOUSES W
      WHERE W.WAREHOUSE_ID LIKE
          #{regionId} || '_' || #{countryId} || '_' || #{locationId} || '_%'


INSERT INTO WAREHOUSES (
    WAREHOUSE_ID,
    WAREHOUSE_NAME,
    LOCATION_ID
) VALUES (
    #{warehouseId},
    #{warehouseName},
    #{locationId}
)

mapper.update:
UPDATE WAREHOUSES
SET WAREHOUSE_NAME = #{warehouseName}
WHERE WAREHOUSE_ID = #{warehouseId}

mapper.select:
SELECT COUNT(DISTINCT WAREHOUSE_ID) FROM INVENTORIES WHERE WAREHOUSE_ID IN
#{warehouseId}
AND QUANTITY >= 1

mapper.delete:
DELETE FROM WAREHOUSES
WHERE WAREHOUSE_ID IN

    #{warehouseId}

DELETE FROM LOCATIONS
WHERE LOCATION_ID IN

    #{locationId}
